function generateBreadcrumb(){const m=window.location.pathname.split("/").filter(e=>e);let o=document.getElementById("breadcrumb-container");if(!o){const e=document.querySelector("main")||document.body;if(!e){console.error("Could not find a <main> or <body> element to attach the breadcrumb to.");return}const a=document.createElement("div");a.id="breadcrumb-container",e.prepend(a),o=a}const n=document.createElement("nav");n.className="breadcrumb";const c=document.createElement("a");c.href="/",c.textContent="Home",n.appendChild(c);let l="";const i=m.filter(e=>e.toLowerCase()!=="index.html");i.forEach((e,a)=>{l+=`/${e}`;const p=a===i.length-1,s=document.createTextNode(" \u203A ");n.appendChild(s);let d=decodeURIComponent(e.replace(/[-_]/g," "));d=d.replace(/\.(html|htm|php|asp|aspx)$/i,"");let r=d.split(" ").map(t=>t.charAt(0).toUpperCase()+t.slice(1)).join(" ");if(r=r.replace(/Exemplar (\d+) (\d+)/,"Exemplar $1.$2"),p){const t=document.createElement("span");t.textContent=r,n.appendChild(t)}else{const t=document.createElement("a");t.href=l,t.textContent=r,n.appendChild(t)}}),o.innerHTML="",o.appendChild(n)}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",generateBreadcrumb):generateBreadcrumb();
